def need(ok,message):
    if not ok:raise RuntimeError(message)


def digest(path):
    need(path.resolve()==path,'Source redirected')
    h=hashlib.sha256()
    with path.open('rb') as stream:
        before=os.fstat(stream.fileno())
        need(stat.S_ISREG(before.st_mode),'Source is not regular')
        for raw in iter(lambda:stream.read(1024**2),b''):h.update(raw)
        after=os.fstat(stream.fileno())
    identity=lambda s:(s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns,s.st_ctime_ns)
    need(identity(before)==identity(after)==identity(path.stat()),'Source changed while hashing')
    return h.hexdigest()


def write(path,data,uid=0,gid=0,mode=0o600):
    need(path.resolve()==path,'Output redirected')
    fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,mode)
    with os.fdopen(fd,'wb') as stream:
        os.fchown(stream.fileno(),uid,gid);os.fchmod(stream.fileno(),mode)
        stream.write(data);stream.flush();os.fsync(stream.fileno())


def folder(path,uid=0,gid=0,mode=0o700):
    need(path.resolve()==path and not path.exists(),'Existing/redirected staging directory preserved')
    path.mkdir(mode=mode);os.chown(path,uid,gid);os.chmod(path,mode)


def tool(name):
    for prefix in ('/usr/bin','/usr/sbin','/bin','/sbin'):
        p=Path(prefix)/name
        if p.is_file():
            s=p.resolve().stat();need(s.st_uid==0 and not s.st_mode&0o022,'Unsafe system tool')
            return str(p)
    raise RuntimeError('Missing required system tool: '+name)


def command(argv,timeout=30,env=None):
    r=subprocess.run(list(map(str,argv)),stdin=subprocess.DEVNULL,capture_output=True,timeout=timeout,
        env=env or {'PATH':'/usr/sbin:/usr/bin:/sbin:/bin','LANG':'C','LC_ALL':'C'})
    return r


def checked(argv,timeout=30,env=None):
    r=command(argv,timeout,env)
    need(r.returncode==0,'Command failed: '+str(argv[0])+' exit='+str(r.returncode)+' '+r.stderr.decode(errors='replace')[-1000:])
    return r.stdout


def unit(name):
    raw=checked([tool('systemctl'),'show',name,'--no-pager',
                 '--property=MainPID,ActiveState,SubState,LoadState,Job,Description,Result,ExecMainStatus'])
    return dict(line.split('=',1) for line in raw.decode().splitlines() if '=' in line)


def ticks(pid):return (Path('/proc')/str(pid)/'stat').read_text().rsplit(')',1)[1].split()[19]


def memory():
    result={}
    for line in Path('/proc/meminfo').read_text().splitlines():
        key,value=line.split(':',1)
        if key in ('Cached','Buffers','AnonPages','Shmem','Dirty','MemAvailable','Slab','PageTables'):
            result[key+'Bytes']=int(value.split()[0])*1024
    return result


def residency(path,length):
    """Only ordinary source files; this is not a DAX residency measurement."""
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
    libc=ctypes.CDLL(None,use_errno=True)
    libc.mmap.argtypes=[ctypes.c_void_p,ctypes.c_size_t,ctypes.c_int,ctypes.c_int,ctypes.c_int,ctypes.c_long]
    libc.mmap.restype=ctypes.c_void_p
    libc.mincore.argtypes=[ctypes.c_void_p,ctypes.c_size_t,ctypes.c_void_p]
    libc.munmap.argtypes=[ctypes.c_void_p,ctypes.c_size_t]
    address=None
    try:
        need(os.fstat(fd).st_size==length,'Measured source length differs')
        from aenv_ub_provider import fsdax
        try:fsdax.validate_fd(fd,length,fs_dax=False)
        except (OSError,ValueError):return None
        address=libc.mmap(None,length,0,1,fd,0)
        need(address not in (None,ctypes.c_void_p(-1).value),'Ordinary file mapping failed')
        page=os.sysconf('SC_PAGE_SIZE');count=(length+page-1)//page
        vec=(ctypes.c_ubyte*count)()
        need(libc.mincore(address,length,vec)==0,'Ordinary cache query failed')
        return sum(min(page,length-i*page) for i,v in enumerate(vec) if v&1)
    finally:
        if address not in (None,ctypes.c_void_p(-1).value):libc.munmap(address,length)
        os.close(fd)


class Demo:
    def __init__(self,state,plan,api):self.state,self.plan,self.api=state,plan,api
    def mark(self,phase,**fields):
        self.state.update(phase=phase,**fields);self.api.atomic(ROOT/'journal.json',self.state)
        print('PHASE='+phase,flush=True)
    def python(self,module,*args):
        code="import sys,runpy;sys.path.insert(0,sys.argv.pop(1));m=sys.argv.pop(1);sys.argv[0]=m;runpy.run_module(m,run_name='__main__')"
        return ['/usr/bin/python3','-I','-B','-c',code,str(ROOT/'code'),module,*map(str,args)]
    def launch(self,label,argv,properties):
        name='aenv-hpc1-'+label+'-'+self.state['runId'][:8]+'.service'
        need(unit(name)['LoadState']=='not-found','Service name already exists')
        row={'name':name,'description':'AgentENV C T1 '+self.state['runId']+' '+label,
             'argvSha256':hashlib.sha256(self.api.encoded(argv)).hexdigest(),'intent':True}
        self.state['units'][label]=row;self.mark('unit_launch_intent',unit=label)
        output=ROOT/(label+'.log')
        flags=['Type=exec','Restart=no','UMask=0077','KillMode=control-group','TimeoutStopSec=90s',
               'LimitNOFILE=65536','LimitCORE=0','WorkingDirectory='+str(WORK),
               'StandardOutput=append:'+str(output),'StandardError=append:'+str(output),
               'Description='+row['description'],*properties]
        checked([tool('systemd-run'),'--quiet','--unit='+name,*['--property='+p for p in flags],'--',*argv])
        value=unit(name);pid=int(value['MainPID'])
        need(value['ActiveState']=='active' and pid>0 and value['Description']==row['description'],'Unit launch not confirmed')
        row.update(pid=pid,ticks=ticks(pid));self.mark('unit_launch_confirmed',unit=label)
        return row
    def bound(self,label):
        row=self.state['units'][label];value=unit(row['name'])
        need('pid' in row and value['Description']==row['description'] and value['ActiveState']=='active'
             and int(value['MainPID'])==row['pid'] and ticks(row['pid'])==row['ticks'],'Owned unit identity changed')
        return row
    def stop(self,label):
        row=self.bound(label);self.mark('unit_stop_intent',unit=label)
        checked([tool('systemctl'),'stop',row['name']],60)
        value=unit(row['name'])
        need(value['ActiveState']=='inactive' and value['MainPID']=='0','Owned unit exit not confirmed')
        row['stopped']=True;self.mark('unit_stopped',unit=label)
    def ready(self,label,path,key,value,seconds=600):
        end=time.monotonic()+seconds
        while time.monotonic()<end:
            self.bound(label)
            if path.exists():
                row=json.loads(path.read_bytes())
                if row.get(key)==value:return row
                need(row.get(key) not in ('unresolved_preserved','unresolved_create','stopped_preserve_resources',
                     'rootfs_stopped_preserve_resources','retirement_stopped_preserve_resources'),'Helper failed; retain resources')
            time.sleep(1)
        raise RuntimeError('Helper readiness timeout; retain resources, never allocate again')
    def measure(self,label):
        rows=[]
        for layer in self.plan['files']:
            path=MIGRATED/'seed/repository/managed-layers'/(layer['digest'].replace(':','_')+'.overlaybd.commit')
            rows.append({'digest':layer['digest'],'bytes':layer['bytes'],'residentBytes':residency(path,layer['bytes'])})
        total=sum(x['residentBytes'] for x in rows) if all(x['residentBytes'] is not None for x in rows) else None
        result={'label':label,'monotonicNs':time.monotonic_ns(),'host':memory(),
                'ordinaryLowerFiles':rows,'ordinaryLowerResidentBytes':total,
                'cacheQueryMethod':'mincore only after statx confirms S_DAX=false; otherwise NA'}
        image=self.plan['container']
        result['sourceContainerResidentBytes']=residency(Path(image['path']),image['bytes'])
        result['processes']=self.process_metrics()
        result['sampleEndMonotonicNs']=time.monotonic_ns();result['sequentialSnapshotNotAtomic']=True
        self.state['samples'].append(result);self.mark('sample_collected',sample=label)
        return result
    def advise_sources(self):
        # Per-file best-effort advice only. Never invoke whole-machine drop_caches.
        for item in self.plan['files']:
            path=MIGRATED/'seed/repository/managed-layers'/(item['digest'].replace(':','_')+'.overlaybd.commit')
            fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
            try:os.posix_fadvise(fd,0,0,os.POSIX_FADV_DONTNEED)
            finally:os.close(fd)
        # The source container is a distinct ordinary file cache, not the UB allocation.
        fd=os.open(self.plan['container']['path'],os.O_RDONLY|os.O_NOFOLLOW)
        try:os.posix_fadvise(fd,0,0,os.POSIX_FADV_DONTNEED)
        finally:os.close(fd)
    def process_metrics(self):
        rows=[]
        def sample(pid,label):
            try:
                start=ticks(pid);values={}
                for line in (Path('/proc')/str(pid)/'smaps_rollup').read_text().splitlines():
                    fields=line.split()
                    if fields and fields[0].rstrip(':') in ('Rss','Pss','Pss_Anon','Pss_File','Pss_Shmem'):
                        values[fields[0].rstrip(':')+'Bytes']=int(fields[1])*1024
                need(ticks(pid)==start,'Process changed while sampling')
                return {'label':label,'pid':pid,'ticks':start,'values':values}
            except (OSError,RuntimeError):return {'label':label,'pid':pid,'values':None}
        rows.append(sample(os.getpid(),'controller'))
        ubse=self.state.get('ubse')
        if ubse:
            try:
                if ticks(ubse['pid'])==ubse['ticks']:rows.append(sample(ubse['pid'],'ubse'))
            except OSError:pass
        broker=self.state.get('viewJournal',{}).get('rootfsBroker',{}).get('pid')
        if broker:
            try:
                parent=next(line.split()[1] for line in (Path('/proc')/str(broker)/'status').read_text().splitlines() if line.startswith('PPid:'))
                if int(parent)==self.state['units']['view']['pid']:rows.append(sample(broker,'dax-broker'))
            except OSError:pass
        for label,row in self.state['units'].items():
            if row.get('pid') and not row.get('stopped'):
                try:self.bound(label)
                except (OSError,RuntimeError):continue
                rows.append(sample(row['pid'],label))
        end=time.monotonic()+3;incomplete=False
        for path in Path('/proc').iterdir():
            if time.monotonic()>end:incomplete=True;break
            if not path.name.isdecimal():continue
            try:
                raw=(path/'cmdline').read_bytes()[:8192]
                variant=next((v for v in ('original','dax') if str(WORK/(v+'-fc')).encode()+b'/' in raw),None)
                if variant and b'--api-sock' in raw:rows.append(sample(int(path.name),'fc-'+variant))
                daemon=next((v for v in ('original','dax') if str(MIGRATED/'artifacts'/v/'bin/uvm-ublk-daemon').encode() in raw),None)
                if daemon and str(WORK).encode() in raw:rows.append(sample(int(path.name),'ublk-'+daemon))
            except (OSError,RuntimeError):continue
        return {'rows':rows,'fcDiscoveryIncomplete':incomplete,'GuestRamVmaAndDeviceCache':None,
                'notAWholeHostPhysicalTotal':True}
    def cli(self,variant,args,timeout=330):
        row=self.bound(variant)
        env={'PATH':'/usr/sbin:/usr/bin:/sbin:/bin','LANG':'C','LC_ALL':'C',
             'HOME':'/home/jwk','XDG_CONFIG_HOME':str(WORK/variant/'cli-config')}
        argv=[tool('nsenter'),'-t',str(row['pid']),'-n','-m','--',tool('setpriv'),
              '--reuid=1204','--regid=1205','--clear-groups',str(MIGRATED/'artifacts'/variant/'bin/aenv'),*args]
        return command(argv,timeout,env)
    def inventory(self,variant):
        r=self.cli(variant,['list','--output','json'])
        need(r.returncode==0,'Dedicated sandbox inventory failed')
        row=json.loads(r.stdout);need(isinstance(row,list),'Unexpected inventory format')
        return row
    def run_guest(self,variant,sid,args):
        self.mark('guest_command_intent',variant=variant,sandboxId=sid)
        r=self.cli(variant,['exec',sid,'timeout','300',*args],330)
        need(r.returncode==0,'Guest command failed; not ignored or extended: '+r.stderr.decode(errors='replace')[-1000:])
        return r.stdout
    def runtime(self,variant):
        staged=json.loads((WORK/'staged.json').read_bytes())
        need(staged['templateId']==TEMPLATE,'Staged template differs')
        path=WORK/variant/'config/runtime.template.toml'
        need(digest(path)==CONFIG_PINS[variant],'Runtime template changed')
        import tomllib
        config=tomllib.loads(path.read_text())
        deps=WORK/variant/'deps'
        config['deps_path']=str(deps)
        config['firecracker']['binary_path']=str(deps/'firecracker/1.15.1-patch-v3/firecracker')
        config['kernel']['image_path']=str(deps/'kernel/vmlinux-6.1.175/vmlinux.bin')
        config['tools']['drive_path']=str(deps/'tools/0.1.1/tools.ext4')
        if variant=='dax':
            index=ROOT/'public/rootfs-index.json'
            config['snapshot']['ub_rootfs_index']=str(index)
            config['snapshot']['ub_rootfs_index_sha256']=hashlib.sha256(index.read_bytes()).hexdigest()
        # Reuse the exact tested TOML emitter from the reviewed preparation module.
        lines=[]
        def emit(value,prefix):
            if prefix:lines.append('['+'.'.join(prefix)+']')
            for key,item in value.items():
                if not isinstance(item,dict):lines.append(key+' = '+json.dumps(item))
            lines.append('')
            for key,item in value.items():
                if isinstance(item,dict):emit(item,prefix+[key])
        emit(config,[]);raw=('\n'.join(lines)+'\n').encode()
        need(tomllib.loads(raw.decode())==config,'Runtime config serialization mismatch')
        output=ROOT/'public'/(variant+'-runtime.toml');write(output,raw,mode=0o644)
        credentials=WORK/variant/'cli-config';folder(credentials,1204,1205)
        folder(credentials/'aenv',1204,1205)
        port=self.plan['variants'][variant]['apiPort']
        key=(WORK/variant/'state/secrets/api-key').read_text().strip()
        write(credentials/'aenv/credentials',('url = '+json.dumps('http://127.0.0.1:'+str(port))+'\napi_key = '+json.dumps(key)+'\n').encode(),1204,1205)
        need(re.fullmatch('[A-Za-z0-9_.~-]{32,256}',key),'API key format invalid')
        envfile=ROOT/(variant+'.env')
        write(envfile,('AENV_API_KEY='+key+'\nAPI_ADDR=127.0.0.1:'+str(port)+'\nAENV_CONFIG_PATH='+str(output)+'\n').encode())
        # A private network namespace starts with forwarding off. Change only this unit's namespace.
        launch=ROOT/'public'/(variant+'-launch.py')
        launch_code=('import os\nfrom pathlib import Path\n'
            'assert os.stat("/proc/self/ns/net").st_ino != '+str(os.stat('/proc/self/ns/net').st_ino)+'\n'
            'Path("/proc/sys/net/ipv4/ip_forward").write_text("1\\n")\n'
            'os.execv('+repr(str(MIGRATED/'artifacts'/variant/'bin/server'))+','+
            repr([str(MIGRATED/'artifacts'/variant/'bin/server')])+')\n')
        write(launch,launch_code.encode(),mode=0o644)
        argv=['/usr/bin/python3','-I','-B',str(launch)]
        self.launch(variant,argv,['User=1204','Group=1205','SupplementaryGroups=985 36',
            'AmbientCapabilities=CAP_SYS_ADMIN CAP_NET_ADMIN','CapabilityBoundingSet=CAP_SYS_ADMIN CAP_NET_ADMIN',
            'PrivateNetwork=yes','PrivateMounts=yes','EnvironmentFile='+str(envfile)])
        end=time.monotonic()+60
        while time.monotonic()<end:
            self.bound(variant)
            r=self.cli(variant,['list','--output','json'],20)
            if r.returncode==0:
                need(json.loads(r.stdout)==[],'Dedicated Runtime not initially empty');return
            time.sleep(1)
        raise RuntimeError('Runtime readiness failed; preserve namespace/service')
    def pair(self,variant):
        need(not self.state['unknownCreate'],'Unconfirmed create must be reconciled before any new create')
        self.runtime(variant);self.advise_sources();self.measure(variant+'-before-create')
        self.state['guests'][variant]=[]
        for i in range(2):
            self.state['unknownCreate']={'variant':variant,'attempt':i}
            if not self.state.get('Guest_created'):self.state['Guest_created']=None
            self.mark('sandbox_create_intent')
            r=self.cli(variant,['start',TEMPLATE,'--detach','--timeout','1200'])
            need(r.returncode==0,'Sandbox creation not acknowledged; no retry, retain intent')
            candidates=[line for line in r.stdout.decode().splitlines() if re.fullmatch('[0-9a-f-]{36}',line.strip())]
            need(len(candidates)==1,'Sandbox ID not confirmed; preserve create intent')
            sid=candidates[0].strip();uuid.UUID(sid)
            self.state['guests'][variant].append(sid);self.state['guestHistory'].append({'variant':variant,'sandboxId':sid})
            self.state['Guest_created']=True;self.state['unknownCreate']=False;self.mark('sandbox_create_acknowledged')
        expected=set(self.state['guests'][variant]);observed={row['sandboxID'] for row in self.inventory(variant)}
        need(observed==expected,'Dedicated Runtime inventory differs from exactly two owned Guests')
        self.measure(variant+'-two-ready')
        a,b=self.state['guests'][variant];marker='/var/tmp/aenv-hpc1-'+self.state['runId']
        disk_check='case $(stat -f -c %T /var/tmp) in tmpfs|ramfs) exit 72;; esac; '
        arch=self.run_guest(variant,a,['sh','-c','set -eu; '+disk_check+'uname -m; printf A > '+marker+'; sync; test "$(cat '+marker+')" = A']).decode().strip()
        need(arch=='aarch64','Guest execution architecture differs')
        self.run_guest(variant,b,['sh','-c','set -eu; '+disk_check+'test ! -e '+marker+'; printf B > '+marker+'; sync'])
        self.run_guest(variant,a,['sh','-c','test "$(cat '+marker+')" = A'])
        self.state['upperIsolation'][variant]={'passed':True,'path':marker,'guestFilesystemNotTmpfs':True,
                                               'guestSyncExecuted':True,'guestArchitecture':arch}
        self.mark('guest_private_upper_isolation_verified')
        for sid in (a,b):
            go=self.run_guest(variant,sid,['sh','-c','set -eu; for p in /usr/local/go/bin/go /usr/bin/go /bin/sh; do if test -x "$p"; then printf "%s\\n" "$p"; exit 0; fi; done; exit 1']).decode().strip()
            need(re.fullmatch(r'/[A-Za-z0-9_./+\-]+',go),'Unexpected Guest Go executable path')
            uploaded=self.cli(variant,['upload',sid,str(ROOT/'public/guest-read-probe'),'/tmp/aenv-hpc1-read-probe'])
            need(uploaded.returncode==0,'Guest read probe upload failed')
            self.run_guest(variant,sid,['chmod','0700','/tmp/aenv-hpc1-read-probe'])
            raw=self.run_guest(variant,sid,['/tmp/aenv-hpc1-read-probe','--max-bytes','16777216','--block-bytes','65536','--',go])
            probe=json.loads(raw)
            need(probe['state']=='completed' and len(probe['files'])==1 and 0<probe['files'][0]['bytes']<=48*1024**2
                 and probe['actualBytes']==2*min(probe['files'][0]['bytes'],8388608),
                 'Guest bounded reads did not complete or selected checksum file exceeds budget')
            checksum=self.run_guest(variant,sid,['sha256sum',go]).decode().split()[0]
            need(re.fullmatch('[0-9a-f]{64}',checksum),'Guest file checksum malformed')
            self.state['guestProbes'].append({'variant':variant,'sandboxId':sid,'path':go,'sha256':checksum,'probe':probe})
            self.mark('guest_read_probe_completed')
        self.measure(variant+'-after-probe')
        self.close_pair(variant)
    def close_pair(self,variant):
        need(not self.state['unknownCreate'],'Unknown create outcome: refuse inventory-only cleanup')
        if not self.state['guests'].get(variant):
            row=self.state['units'][variant];status=unit(row['name'])
            if (status['Description']==row['description'] and status['MainPID']=='0'
                    and status['ActiveState'] in ('inactive','failed') and status['Job'] in ('','0')):
                # No create intent, or every known delete was acknowledged, plus attributable unit termination.
                row['stopped']=True;self.mark('runtime_terminal_without_pending_guest',variant=variant);return
            if variant not in self.state['guests']:
                self.stop(variant);return
        for sid in list(self.state['guests'].get(variant,[])):
            self.mark('sandbox_delete_intent',sandboxId=sid)
            r=self.cli(variant,['delete',sid])
            need(r.returncode==0,'Sandbox deletion not acknowledged; preserve Runtime')
            self.state['guests'][variant].remove(sid);self.mark('sandbox_delete_acknowledged')
        need(self.inventory(variant)==[],'Dedicated sandbox inventory still nonempty')
        self.stop(variant);self.measure(variant+'-guests-exited')
    def publish(self):
        owner_dir=WORK/'sdk-owner'
        need(not owner_dir.exists(),'Old SDK owner intent exists; never allocate again')
        image=self.plan['container'];need(digest(Path(image['path']))==image['sha256'],'T1 container content changed')
        source={'objectId':'image-'+image['sha256'],'generation':image['sha256'][:32],
                'sha256':'sha256:'+image['sha256'],'bytes':image['bytes'],'socket':str(owner_dir/'data.sock')}
        catalog={'version':1,'objects':[{'path':image['path'],'backing':source}]}
        write(ROOT/'public/catalog.json',self.api.encoded(catalog),mode=0o644)
        config={'version':1,'mode':'pmem','role':'publish','workDir':str(owner_dir),
            'adapter':str(ROOT/'public/libaenv-ub.so'),'adapterSha256':'sha256:'+NATIVE_SHA,'region':'default',
            'logicalBudgetBytes':1811939328,'maxCoverageBytes':4294967296,
            'hostPmemReleaseReceipt':str(ROOT/'public/local-release.json'),
            'readers':[],'catalog':str(ROOT/'public/catalog.json')}
        write(ROOT/'public/sdk-config.json',self.api.encoded(config),mode=0o644)
        self.state['sdkLaunchAttempted']=True;self.state['SDK_called']=None;self.mark('sdk_publication_intent')
        self.launch('sdk',self.python('aenv_ub_provider','serve',str(ROOT/'public/sdk-config.json'),'--run'),
                    ['User=1204','Group=1205','SupplementaryGroups=985','NoNewPrivileges=yes','CapabilityBoundingSet=',
                     'AmbientCapabilities=','LimitMEMLOCK=4294967296'])
        owner=self.ready('sdk',owner_dir/'owner.json','state','serving')
        manifest=json.loads((owner_dir/'replicas.json').read_bytes())
        need(manifest['mode']=='pmem' and manifest['readers']==[] and len(manifest['replicas'])==1
             and manifest['replicas'][0]['identity']=={k:source[k] for k in ('objectId','generation','sha256','bytes')},
             'SDK publication identity differs')
        self.state.update(source=source,publication=manifest,ownerJournal=owner,SDK_called=True);self.mark('sdk_publication_confirmed')
        owner_process=self.bound('sdk')
        from aenv_ub_provider import stored, host_pmem_rootfs, contract
        files=[{'name':f['name'],'replica':{'brokerSocket':self.plan['rootfsBrokerSocket'],
            'objectName':'aenv_'+uuid.uuid4().hex,'generation':uuid.uuid4().hex,'layerDigest':f['digest'],
            'fileBytes':f['bytes'],'mappingBytes':((f['bytes']+stored.HEADER_BYTES+stored.ALIGN-1)//stored.ALIGN)*stored.ALIGN,
            'allowRepositoryFallback':False}} for f in self.plan['files']]
        config={'version':1,'workDir':str(ROOT/'view'),'source':source,'ownerUid':1204,
            'ownerPid':owner_process['pid'],'ownerStartTicks':owner_process['ticks'],'publication':manifest,
            'releaseReceipt':str(ROOT/'public/local-release.json'),'kernelRelease':platform.release(),
            'moduleSrcversion':'C2BBB64D75C618180ABA3A6','files':files,'brokerSocket':self.plan['rootfsBrokerSocket'],
            'brokerGid':1205,'runtimeIndex':str(ROOT/'public/rootfs-index.json'),'payloadResponses':2}
        pin=host_pmem_rootfs.plan(config)['configSha256']
        write(ROOT/'rootfs-config.json',contract.canonical(config));self.state['viewConfigSha256']=pin
        self.state['viewLaunchAttempted']=True;self.mark('dax_view_launch_intent')
        self.launch('view',self.python('aenv_ub_provider.host_pmem_rootfs','serve','--config',str(ROOT/'rootfs-config.json'),
                    '--expected-config-sha256',pin,'--approval','CREATE_READONLY_ROOTFS_HOST_PMEM'),
                    ['PrivateMounts=yes','CapabilityBoundingSet=CAP_SYS_ADMIN CAP_SETUID CAP_SETGID CAP_DAC_READ_SEARCH'])
        journal=self.ready('view',ROOT/'view/host-pmem-session.json','phase','rootfs_broker_ready')
        evidence=journal.get('rootfsBroker',{}).get('fileEvidence',[])
        need(len(evidence)==8 and all(row['activeDax'] and row['readonlyMount'] for row in evidence),
             'Actual eight readonly DAX files not verified')
        self.state['viewJournal']=journal;self.mark('rootfs_dax_broker_ready')
    def view(self,action,allow_refusal=False):
        from aenv_ub_provider import host_pmem_cli
        config=json.loads((ROOT/'rootfs-config.json').read_bytes())
        result=host_pmem_cli.request_action(config,self.state['viewConfigSha256'],action)
        need(allow_refusal or result.get('state')!='refused_preserve_resources','DAX action refused; retain UB')
        return result
    def release(self):
        need(not self.state['unknownCreate'] and all(not ids for ids in self.state['guests'].values()),
             'Unknown/live Guests prohibit backing release')
        for label in ('original','dax'):
            row=self.state['units'].get(label)
            need(row is None or row.get('stopped') is True,'Runtime consumers have not exited')
        if self.state.get('viewLaunchAttempted') and not self.state.get('viewRetiredConfirmed'):
            status=unit(self.state['units']['view']['name'])
            if status['ActiveState']=='active':
                need(not self.state.get('viewRetirementRequestPending'),
                     'Prior DAX retirement response unconfirmed; preserve, do not implicitly retry')
                self.bound('view');self.mark('dax_retirement_intent')
                self.state['viewRetirementRequestPending']=True;self.mark('dax_retirement_request_pending')
                result=self.view('retire',allow_refusal=True)
                self.state['viewRetirementRequestPending']=False;self.mark('dax_retirement_response_acknowledged')
                need(result['state']=='local_resources_released','Local view release not confirmed')
                self.wait_exit('view')
            else:
                # Explicit lost-ack recovery requires both durable kernel-release evidence and successful helper exit.
                row=self.state['units']['view']
                journal=json.loads((ROOT/'view/host-pmem-session.json').read_bytes())
                from aenv_ub_provider import host_pmem_guard
                released=host_pmem_guard.read_root_receipt(ROOT/'public/local-release.json')
                need(status['ActiveState']=='inactive' and status['MainPID']=='0'
                     and status['Description']==row['description'] and status['Result']=='success'
                     and status['ExecMainStatus']=='0' and journal['phase']=='local_resources_released'
                     and released['mountAbsent'] is True and released['localVolumeAbsent'] is True,
                     'No attributable complete DAX retirement; preserve UB')
                row['stopped']=True
            self.state['viewRetiredConfirmed']=True;self.mark('dax_retirement_confirmed')
            self.state['viewRetirementRequestPending']=False
        elif not self.state.get('viewLaunchAttempted') and self.state.get('sdkLaunchAttempted') and not self.state.get('viewRetiredConfirmed'):
            # A proved never-submitted view is distinct from an unknown launch.
            need('view' not in self.state['units'] and not (ROOT/'view').exists(),'Unexpected view state; refuse pre-view cancellation')
            publication=self.state['publication'];source=self.state['source'];owner=self.bound('sdk')
            from aenv_ub_provider import host_pmem_guard
            cancellation={'version':1,'scope':'local-host-pmem','state':'released',
                'publication':host_pmem_guard.publication_binding(publication,source),'source':source,
                'bootId':Path('/proc/sys/kernel/random/boot_id').read_text().strip(),'ownerUid':1204,
                'ownerPid':owner['pid'],'ownerStartTicks':owner['ticks'],'volumeCreated':False,
                'creationOutcome':'not_attempted','volumeUuid':None,'volumeId':None,
                'mountAbsent':True,'localVolumeAbsent':True,'sharedBackingReleaseAuthorized':False}
            write(ROOT/'public/local-release.json',self.api.encoded(cancellation),mode=0o644)
            self.state['viewRetiredConfirmed']=True;self.mark('view_never_submitted_receipt_written')
        if self.state.get('sdkLaunchAttempted') and not self.state.get('sdkRetiredConfirmed'):
            row=self.state['units']['sdk']
            prior=json.loads((WORK/'sdk-owner/owner.json').read_bytes())
            if prior.get('state')!='released':
                need(not self.state.get('sdkRetirementRequestPending'),
                     'Prior SDK retirement response unconfirmed; preserve, do not implicitly retry')
                self.bound('sdk');self.mark('sdk_retirement_intent')
                self.state['sdkRetirementRequestPending']=True;self.mark('sdk_retirement_request_pending')
                r=command([tool('setpriv'),'--reuid=1204','--regid=1205','--groups=985',
                       *self.python('aenv_ub_provider','retire',str(WORK/'sdk-owner'))],600)
                response=json.loads(r.stdout)
                if response.get('state') in ('released','refused'):
                    self.state['sdkRetirementRequestPending']=False;self.mark('sdk_retirement_response_acknowledged')
                need(r.returncode==0 and response.get('state')=='released','SDK release not acknowledged')
            self.wait_exit('sdk')
            owner=json.loads((WORK/'sdk-owner/owner.json').read_bytes())
            need(owner['state']=='released' and owner.get('finalize_acknowledged') is True
                 and owner.get('base_post_sha256_verified') is True
                 and all(x.get('creation_confirmed') and x.get('delete_acknowledged') for x in owner['objects']),
                 'SDK/base integrity/global deletion not fully confirmed')
            self.state['finalOwnerJournal']=owner
            self.state['sdkRetiredConfirmed']=True;self.mark('sdk_global_release_confirmed')
            self.state['sdkRetirementRequestPending']=False
        self.restore_acl();self.mark('local_resources_released_candidate_module_retained')
        self.state['kernelAfterRelease']={
            'moduleSource':Path('/sys/module/obmm/srcversion').read_text().strip(),
            'moduleReferences':Path('/sys/module/obmm/refcnt').read_text().strip(),
            'regionDevices':[p.name for p in Path('/dev').glob('obmm_shmdev*')],
            'scope':'Observed after owned release; not proof that all allocator/pool physical memory returned'}
        self.mark('post_release_kernel_observation_recorded')
    def wait_exit(self,label):
        row=self.state['units'][label];end=time.monotonic()+30
        while time.monotonic()<end:
            value=unit(row['name'])
            if (value['MainPID']=='0' and value['ActiveState']=='inactive' and value['Description']==row['description']
                    and value['Result']=='success' and value['ExecMainStatus']=='0'):
                row['stopped']=True;self.mark('helper_exit_acknowledged',helper=label);return
            need(value['ActiveState']!='failed','Owned helper failed during retirement')
            time.sleep(1)
        raise RuntimeError('Helper exit unconfirmed')
    def restore_acl(self):
        for item in self.state['acl']:
            info=Path(item['path']).stat()
            need(info.st_rdev==item['rdev'] and info.st_ino==item['inode'],'Device changed; refuse ACL restoration')
            original=(ROOT/item['backup']).read_bytes()
            current=checked([tool('getfacl'),'-p',item['path']])
            if current==original:
                item['restored']=True;continue
            need(item.get('appliedAclSha256')==hashlib.sha256(current).hexdigest(),
                 'ACL changed outside this task; preserve it rather than overwrite')
            checked([tool('setfacl'),'--restore='+str(ROOT/item['backup'])])
            need(checked([tool('getfacl'),'-p',item['path']])==original,'ACL restoration differs')
            item['restored']=True
        self.mark('device_acl_restored')


def prepare_sources():
    manifest=json.loads((WORK/'provider-source-manifest.json').read_bytes())
    need(hashlib.sha256(json.dumps(manifest,sort_keys=True).encode()).hexdigest()==SOURCE_SHA,'Provider source manifest changed')
    folder(ROOT/'code',mode=0o755);folder(ROOT/'code/aenv_ub_provider',mode=0o755)
    for relative,pin in manifest.items():
        need(re.fullmatch(r'(aenv_ub_provider|tests)/[A-Za-z0-9_]+\.py',relative),'Unexpected source member')
        path=WORK/'provider-code'/relative
        need(path.resolve()==path and path.stat().st_size<256*1024,'Source redirected/oversized')
        raw=path.read_bytes();need(hashlib.sha256(raw).hexdigest()==pin,'Provider source file changed')
        if relative.startswith('aenv_ub_provider/'):
            write(ROOT/'code'/relative,raw,mode=0o644)
    native=Path('/var/lib/agentenv-c-rootfs-maintenance-v1/build/libaenv-ub-sdk13.so')
    need(digest(native)==NATIVE_SHA,'Native C adapter changed')
    write(ROOT/'public/libaenv-ub.so',native.read_bytes(),gid=1205,mode=0o640)
    raw=zlib.decompress(base64.b64decode(PROBE,validate=True));need(hashlib.sha256(raw).hexdigest()==PROBE_SHA,'Guest probe differs')
    write(ROOT/'public/guest-read-probe',raw,mode=0o755)
    for relative,pin in PINS.items():need(digest(MIGRATED/relative)==pin,'Runtime binary/dependency changed')
    for variant in ('original','dax'):
        deps=WORK/variant/'deps';folder(deps,1204,1205)
        for relative,pin in PINS.items():
            prefix='artifacts/'+variant+'/deps/'
            if not relative.startswith(prefix):continue
            source=MIGRATED/relative;dest=deps/relative[len(prefix):]
            current=deps
            for part in dest.relative_to(deps).parts[:-1]:
                current=current/part
                if not current.exists():folder(current,1204,1205)
                need(current.resolve()==current and current.stat().st_uid==1204,'Dependency parent differs')
            if dest.suffix=='.json':write(dest,source.read_bytes(),1204,1205)
            else:os.link(source,dest)
        base=deps/'overlaybd'
        for relative in ('etc','etc/overlaybd'):
            path=base/relative
            if not path.exists():folder(path,1204,1205)
            need(path.resolve()==path and path.stat().st_uid==1204 and not path.stat().st_mode&0o022,
                 'OverlayBD config staging parent untrusted')
        config=base/'etc/overlaybd/overlaybd.json'
        need(not config.exists(),'Unreviewed dependency config preserved')
        clean={'logConfig':{'logLevel':1,'logPath':str(WORK/variant/'logs/overlaybd-tools.log')},
               'cacheConfig':{'cacheType':'file','cacheDir':str(WORK/variant/'state/overlaybd-cache'),
                              'cacheSizeGB':1,'refillSize':262144,'blockSize':65536},
               'credentialFilePath':'','credentialConfig':{},'ioEngine':0,
               'p2pConfig':{'enable':False},'enableAudit':False,'registryFsVersion':'v2'}
        write(config,json.dumps(clean).encode(),1204,1205)
    sys.path.insert(0,str(ROOT/'code'))


def publish_report(state,api,action):
    for key,path in (('latestSdkOwner',WORK/'sdk-owner/owner.json'),('latestViewJournal',ROOT/'view/host-pmem-session.json')):
        if path.exists() and path.resolve()==path and path.stat().st_size<=512*1024:
            state[key]=json.loads(path.read_bytes())
    owner=state.get('latestSdkOwner',{})
    if owner.get('finalize_acknowledged') or any(x.get('allocation_attempted') for x in owner.get('objects',[])):
        state['SDK_called']=True
    api.atomic(ROOT/'report.json',state)
    public=Path('/var/lib/agentenv-c-rootfs-preflight-v1')/('maintenance-'+action+'-v1.json')
    if public.exists():
        old=public.read_bytes()
        if json.loads(old).get('scope')!=SCOPE:
            backup=public.with_name('maintenance-'+action+'-before-hpc1.json')
            need(not backup.exists(),'Historical receipt backup already exists; preserve')
            write(backup,old)
    api.atomic(public,state);os.chown(public,0,1205);os.chmod(public,0o640)


def main():
    p=argparse.ArgumentParser();p.add_argument('action',choices=('plan','activate','restore'),nargs='?',default='plan');p.add_argument('--approval')
    args=p.parse_args()
    if args.action=='plan':
        print(json.dumps({'humanApprovalScope':SCOPE,'logicalUbRequestBytes':1811939328,
            'postMapCoverageGuardBytes':4294967296,'physicalHardQuota':False,'maxConcurrentGuests':2,
            'variants':['original','dax'],'GuestCommandSeconds':300,'CLISeconds':330,'defaultChanges':False}));return
    need(os.getuid()==os.geteuid()==0 and args.approval==TRANSPORT,'Explicitly queued C root action required')
    expected=json.loads(Path('/var/lib/agentenv-c-rootfs-preflight-v1/receipt.json').read_bytes())
    need(expected['machineId']==Path('/etc/machine-id').read_text().strip()
         and expected['bootId']==Path('/proc/sys/kernel/random/boot_id').read_text().strip()
         and expected['kernel']==platform.release(),'C preflight context changed')
    need(Path('/sys/module/obmm/srcversion').read_text().strip()=='C2BBB64D75C618180ABA3A6'
         and Path('/sys/module/obmm/parameters/pmem_ro_enable').read_text().strip()=='Y','Candidate OBMM not enabled')
    module_journal=json.loads(Path('/var/lib/agentenv-c-rootfs-maintenance-v1/module/journal.json').read_bytes())
    expected_ubse=module_journal['currentProcess']
    actual_ubse=checked([tool('systemctl'),'show','ubse.service','--property=MainPID','--value']).decode().strip()
    need(module_journal['phase']=='candidate_loaded_ubse_active' and actual_ubse==str(expected_ubse['pid'])
         and ticks(expected_ubse['pid'])==expected_ubse['ticks'],'UBSE identity changed since approved maintenance')
    plan_raw=(WORK/'rootfs-input-plan.json').read_bytes()
    need(hashlib.sha256(plan_raw).hexdigest()==PLAN_SHA,'Reviewed T1 input plan changed')
    plan=json.loads(plan_raw)
    need(plan['templateId']==TEMPLATE and plan['logicalUbRequestBytes']==1811939328
         and plan['proposedMaxCoverageBytes']==4294967296 and len(plan['files'])==8,'Reviewed T1 plan differs')
    # Transport helper is read only from the already root-owned pinned root-relay source.
    namespace={'__name__':'trusted_root_transport'}
    runner=Path('/var/lib/agentenv-root-relay/root-relay.py')
    need(runner.stat().st_uid==0 and not runner.stat().st_mode&0o022,'Root transport untrusted')
    exec(compile(runner.read_bytes(),str(runner),'exec'),namespace)
    api=namespace['api_module']()
    if args.action=='restore':
        need(ROOT.resolve()==ROOT and ROOT.stat().st_uid==0,'Unknown demo work root')
        state=json.loads((ROOT/'journal.json').read_bytes())
        sys.path.insert(0,str(ROOT/'code'));demo=Demo(state,plan,api)
        need(not state['unknownCreate'],'Unknown create must be reconciled, never clear from empty inventory alone')
        try:
            if state['phase'] not in ('local_resources_released_candidate_module_retained','C_T1_TWO_GUESTS_PER_VARIANT_SMOKE_RELEASED'):
                for variant in ('original','dax'):
                    if variant in state['units'] and not state['units'][variant].get('stopped'):demo.close_pair(variant)
                demo.release()
        finally:publish_report(state,api,'restore')
        return
    for name in ('systemd-run','systemctl','setpriv','nsenter','setfacl','getfacl','ip','iptables','mount','umount'):tool(name)
    need(not ROOT.exists(),'Prior UB/demo intent exists; explicit recovery only, never allocate a new name')
    need(Path('/sys/module/obmm/refcnt').read_text().strip()=='0'
         and not list(Path('/dev').glob('obmm_shmdev*')),'Existing local UB references/regions; stop before allocation')
    folder(ROOT,mode=0o755);folder(ROOT/'public',mode=0o755)
    state={'version':1,'scope':SCOPE,'runId':uuid.uuid4().hex,'phase':'prepared','units':{},'guests':{},
           'unknownCreate':False,'samples':[],'guestProbes':[],'guestHistory':[],'upperIsolation':{},'acl':[],'netSavingsBytes':None,
           'crossNodePhysicalSharingAccepted':False,'fullWorkloadComparisonExecuted':False,'Guest_created':False,'SDK_called':False}
    state.update(ubse=expected_ubse,inputPlanSha256=PLAN_SHA,logicalUbRequestBytes=1811939328,
                 postMapCoverageGuardBytes=4294967296,physicalHardQuota=False,maxConcurrentGuests=2,
                 ubPhysicalLocality='Not established; only consumer node C is tested')
    demo=Demo(state,plan,api);demo.mark('prepared_before_side_effects');publish_report(state,api,'activate')
    try:
        prepare_sources()
        for name in ('/dev/obmm','/dev/ublk-control'):
            path=Path(name);s=path.stat();need(stat.S_ISCHR(s.st_mode),'Expected device not present')
            backup='acl-'+path.name+'.txt';raw=checked([tool('getfacl'),'-p',name]);write(ROOT/backup,raw)
            state['acl'].append({'path':name,'rdev':s.st_rdev,'inode':s.st_ino,'backup':backup,'restored':False})
            demo.mark('device_acl_intent');checked([tool('setfacl'),'-m','u:1204:rw',name])
            state['acl'][-1]['appliedAclSha256']=hashlib.sha256(checked([tool('getfacl'),'-p',name])).hexdigest()
            demo.mark('device_acl_applied')
        demo.pair('original')
        for item in plan['files']:
            path=MIGRATED/'seed/repository/managed-layers'/(item['digest'].replace(':','_')+'.overlaybd.commit')
            need(digest(path)==item['digest'][7:],'Original lower changed during baseline')
        state['originalLowerIntegrityAfterExit']=True;demo.mark('original_lower_integrity_verified_before_candidate')
        demo.publish()
        state['brokerBeforeGuests']=demo.view('status');demo.mark('dax_ready_for_guests')
        demo.pair('dax')
        state['brokerAfterGuests']=demo.view('status')
        need(state['brokerAfterGuests']['broker']['readRequests']>0 and state['brokerAfterGuests']['broker']['readBytes']>0,
             'No actual UB/DAX broker reads observed')
        state['daxLifecycleLowerReadBytesAfterReady']=state['brokerAfterGuests']['broker']['readBytes']-state['brokerBeforeGuests']['broker']['readBytes']
        state['daxReadCounterWindow']='Broker ready through Runtime startup, two restores, Guest probes and deletion; not pure probe I/O'
        need(len(state['guestProbes'])==4
             and len({(row['path'],row['sha256']) for row in state['guestProbes']})==1,
             'Original/candidate Guest base file path/content differs')
        state['guestBaseFileContentMatchedAcrossVariants']=True
        demo.mark('dax_guest_io_collected')
        demo.release()
        state['functionalSmokePassed']=True;demo.mark('C_T1_TWO_GUESTS_PER_VARIANT_SMOKE_RELEASED')
    except BaseException as error:
        cleanup_error=None;cleaned=False
        if not state['unknownCreate']:
            try:
                for variant in ('original','dax'):
                    if variant in state['units'] and not state['units'][variant].get('stopped'):demo.close_pair(variant)
                if state.get('sdkLaunchAttempted') and 'publication' not in state:
                    owner=json.loads((WORK/'sdk-owner/owner.json').read_bytes())
                    status=unit(state['units']['sdk']['name'])
                    need(not state.get('viewLaunchAttempted') and owner.get('state')=='released'
                         and owner.get('finalize_acknowledged') is True and status['MainPID']=='0'
                         and status['Description']==state['units']['sdk']['description']
                         and status['ActiveState'] in ('failed','inactive')
                         and all(x.get('creation_confirmed') and x.get('delete_acknowledged') for x in owner.get('objects',[])),
                         'Unconfirmed pre-publication SDK operation; preserve, never allocate again')
                    state['units']['sdk']['stopped']=True
                    state['sdkRetiredConfirmed']=True;state['viewRetiredConfirmed']=True
                    state['finalOwnerJournal']=owner
                demo.release();cleaned=True
            except BaseException as cleanup:
                cleanup_error=str(cleanup)[-1500:]
        demo.mark('smoke_failed_owned_resources_released' if cleaned else 'stopped_preserve_resources',
                  functionalSmokePassed=False,errorType=type(error).__name__,reason=str(error)[-1500:],cleanupError=cleanup_error)
        raise
    finally:
        publish_report(state,api,'activate')
    print(json.dumps({'status':state['phase'],'report':str(ROOT/'report.json'),'netSavingsBytes':None,
                      'fullWorkloadComparisonExecuted':False,'candidateModuleRetained':True}))


if __name__=='__main__':
    try:main()
    except Exception as e:
        print(json.dumps({'status':'C_T1_DEMO_STOPPED_PRESERVE_RESOURCES','reason':str(e)[-1500:]}));raise SystemExit(1)
